-- 1. Categories
INSERT INTO public.categories (id, name, slug, description, accent) VALUES
  (1, 'Music & Sonic Arts', 'music', 'Indie bands, acoustic courtyard sessions, classical-folk fusion, and late-evening soundscapes.', '#C85A32'),
  (2, 'Cultural & Performing Arts', 'cultural', 'Contemporary choreography, folk theatre, spoken word, and ensemble stage productions.', '#8C2D4B'),
  (3, 'Tech & Build Sprints', 'technical', 'Autonomous robotics showcases, 24-hour hardware hackathons, and open-source build labs.', '#2B6E63'),
  (4, 'Hands-On Workshops', 'workshops', 'Terracotta wheel pottery, woodblock textile printing, analog zine-making, and lino-cut studio sessions.', '#D48C28'),
  (5, 'Gaming & Tabletop Arena', 'gaming', 'Retro arcade showdowns, indie game playtests, blitz chess, and cooperative tabletop campaigns.', '#3D5A80'),
  (6, 'Community & Campus Life', 'community', 'Courtyard film screenings, heritage walks, culinary pop-ups, and midnight astronomy circles.', '#6B4E71'),
  (7, 'Sports & Collegiate Contests', 'sports', 'Inter-collegiate athletics, 3v3 basketball, table tennis, and cross-country runs.', '#2A7B4C'),
  (8, 'Entrepreneurship & Venture Lab', 'entrepreneurship', 'Student startup pitches, venture showcases, angel feedback, and founder speed-dating.', '#B45309')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, description = EXCLUDED.description, accent = EXCLUDED.accent;

-- 2. Festivals
INSERT INTO public.festivals (id, name, tagline, theme, description, start_date, end_date, banner) VALUES
  (1, 'Navrang Autumn Confluence 2026', 'Four days of courtyard music, living crafts, and contemporary movement.', 'Living Heritage & Contemporary Sound', 'A flagship autumn celebration bringing acoustic ensembles, ceramicists, contemporary dancers, and culinary storytellers under the banyan canopies.', '2026-11-12', '2026-11-15', 'hero_festival.jpg'),
  (2, 'Yantra & Verse: Tech-Art Symposium', 'Where autonomous machines, kinetic sculptures, and creative code meet.', 'Human-Scale Technology & Kinetic Art', 'A cross-disciplinary festival uniting robotics builders, hardware hackers, and interactive media designers for hands-on sprints and live demonstrations.', '2026-11-18', '2026-11-20', 'tech_robotics.jpg'),
  (3, 'Mitti & Ink Guild Week', 'Slow down and make something tangible with clay, timber, and natural dyes.', 'Tactile Craft & Printmaking', 'An intimate studio festival dedicated to wheel-thrown terracotta, carved woodblock textiles, letterpress zines, and material experimentation.', '2026-11-22', '2026-11-24', 'workshop_craft.jpg'),
  (4, 'Apex Collegiate Arena & Esports Invitational 2026', 'High-octane collegiate athletics, 3v3 basketball, and competitive esports leagues.', 'Collegiate Athletics & Competitive Gaming', 'A celebration of campus athleticism and digital sportsmanship, uniting varsity competitors, casual gamers, and track champions.', '2026-11-27', '2026-11-29', 'sports_arena.jpg'),
  (5, 'Kolkata Genesis: Venture & Innovation Summit 2026', 'Empowering student founders, hardware builders, and social enterprise prototypes.', 'Student Entrepreneurship & Venture Prototyping', 'A summit of investor pitches, product teardowns, speed-mentoring, and demo-day exhibitions in the campus incubation hub.', '2026-12-02', '2026-12-04', 'entrepreneur_pitch.jpg'),
  (6, 'Alpona Open-Air Cultural & Theatre Carnival 2026', 'Midnight street theatre, folk ensembles, midnight cinema, and campus food lanes.', 'Performing Arts, Dramatic Expression & Folk Theatre', 'A winter street theatre and folk carnival weaving through heritage courtyards with lanterns, puppetry, and ensemble movement.', '2026-12-08', '2026-12-11', 'theatre_carnival.jpg')
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, tagline = EXCLUDED.tagline, theme = EXCLUDED.theme, description = EXCLUDED.description, banner = EXCLUDED.banner;

