-- 5. Events Catalogue (38 Flagship Campus Events)
INSERT INTO public.events (
  id, category_id, festival_id, name, subtitle, description, venue, start_at, end_at, price, max_seats, poster, featured, published, artists, terms
) VALUES
  (1, 1, 1, 'Dusk Raga & Indie Folk Session', 'Live sitar, acoustic guitar, and percussion ensemble under the courtyard festoon lights', 'Experience an atmospheric golden-hour concert blending Hindustani slide strings with contemporary indie folk songwriting. Bring a woven mat, grab spiced chai from the courtyard stall, and settle in.', 'Banyan Open-Air Amphitheatre', '2026-11-12T17:30:00+05:30', '2026-11-12T20:30:00+05:30', 150, 40, 'music_concert.jpg', true, true, '[]'::jsonb, ''),
  (2, 2, 1, 'Katha & Kinetic: Contemporary Dance Showcase', 'Six original movement pieces exploring rhythm, architecture, and urban memory', 'Choreographed by student ensembles and visiting movement artists, Katha & Kinetic pairs live tabla and cello accompaniment with expressive contemporary staging.', 'Gulmohar Conservatory Hall', '2026-11-12T18:00:00+05:30', '2026-11-12T20:00:00+05:30', 100, 35, 'cultural_dance.jpg', true, true, '[]'::jsonb, ''),
  (3, 6, 1, 'Rooftop 16mm Short Film & Chai Circle', 'Independent student cinema screened under the stars with director conversations', 'After the main stage winds down, head up to the Observatory Lawn for five restored 16mm and digital short films shot across West Bengal, followed by an open conversation with the filmmakers.', 'Observatory Terrace & Lawn', '2026-11-12T20:45:00+05:30', '2026-11-12T22:30:00+05:30', 0, 18, 'hero_festival.jpg', false, true, '[]'::jsonb, ''),
  (4, 4, 3, 'Mitti & Indigo: Wheel Pottery & Woodblock Studio', 'Throw your own terracotta vessel and print a natural-dyed linen tote', 'Guided by third-generation master potters and campus textile researchers, this tactile three-hour studio walks you through centering river clay on the wheel and carving geometric woodblocks.', 'Terracotta Craft & Print Studio', '2026-11-13T10:00:00+05:30', '2026-11-13T13:00:00+05:30', 250, 5, 'workshop_craft.jpg', true, true, '[]'::jsonb, ''),
  (16, 2, 1, 'Chhau & Contemporary Movement Ensemble', 'Acrobatic martial folk dance fused with modern improvisational stage choreography', 'Performers from Purulia combine dynamic martial movements and vibrant masks with live accompaniment by shehnai and dhamsa drums.', 'Banyan Open-Air Amphitheatre', '2026-11-13T18:00:00+05:30', '2026-11-13T20:30:00+05:30', 200, 80, 'cultural_dance.jpg', true, true, '[]'::jsonb, ''),
  (21, 1, 1, 'Late-Night Ambient Soundscape & Modular Synth', 'Hypnotic analog synth drifts and binaural acoustic textures over the rooftop lawn', 'Seated on floor cushions, listen to quadraphonic modular synth patches and field recordings captured along the Hooghly river.', 'Observatory Terrace & Lawn', '2026-11-13T22:00:00+05:30', '2026-11-13T23:45:00+05:30', 300, 18, 'music_concert.jpg', true, true, '[]'::jsonb, ''),
  (6, 5, 1, 'Pixel & Pawn: Retro Arcade + Catan Guild Night', 'CRT arcade cabinets, indie local-co-op showcases, and tabletop strategy brackets', 'The Brick Lounge transforms into a warm analog-digital playroom. Test student-built indie platformers on custom arcade cabinets or join a four-player tabletop strategy tournament.', 'The Brick Lounge & Arcade Commons', '2026-11-14T16:00:00+05:30', '2026-11-14T20:00:00+05:30', 80, 28, 'gaming_arcade.jpg', true, true, '[]'::jsonb, ''),
  (20, 1, 1, 'Courtyard Acoustic Jam & Open Mic', 'Warm acoustic songwriting, cajon grooves, and vocal harmonies open to campus musicians', 'Step up to the courtyard mic or relax with kulhad chai as student singer-songwriters share original indie and folk songs.', 'Banyan Open-Air Amphitheatre', '2026-11-14T18:00:00+05:30', '2026-11-14T21:00:00+05:30', 0, 75, 'music_concert.jpg', false, true, '[]'::jsonb, ''),
  (34, 6, 1, 'Midnight Astronomy & Stargazing Circle', 'Observation of planetary alignments and autumn constellations with laser constellation guides', 'Peer through refracting telescopes as science department fellows explain celestial navigation and stellar lifecycles.', 'Observatory Terrace & Lawn', '2026-11-15T22:30:00+05:30', '2026-11-16T01:30:00+05:30', 0, 18, 'hero_festival.jpg', false, true, '[]'::jsonb, ''),
  (13, 3, 2, 'Autonomous Rover Navigation Sprint', 'Algorithmic pathfinding through simulated lunar obstacle courses with real LiDAR telemetry', 'Test your autonomous algorithms on student-engineered quad-wheel rovers. Teams receive calibrated LiDAR and depth sensors to navigate an obstacle course in real time.', 'Foundry Makerspace & Robotics Lab', '2026-11-18T10:00:00+05:30', '2026-11-18T14:00:00+05:30', 150, 30, 'tech_robotics.jpg', true, true, '[]'::jsonb, ''),
  (5, 3, 2, 'RoverForge: Autonomous Micro-Rover & Swarm Exhibition', 'Intimate studio demo of student-built terrain rovers and bio-inspired sensors', 'Skip the crowded auditoriums and step inside the Foundry Makerspace. Twelve student hardware teams demonstrate custom-milled suspension rovers, acoustic swarm navigation, and solar telemetry boards.', 'Foundry Makerspace & Robotics Lab', '2026-11-18T14:00:00+05:30', '2026-11-18T17:00:00+05:30', 0, 30, 'tech_robotics.jpg', false, true, '[]'::jsonb, ''),
  (9, 3, 2, 'SonicCircuit: 12-Hour DIY Synthesizer & Audio DSP Sprint', 'Solder analog oscillators or code microcontroller sound engines from scratch', 'Bring your headphones and curiosity. Teams of two spend twelve hours building playable pocket synthesizers using timer ICs, piezo pickups, and embedded Rust/C++ audio DSP.', 'Foundry Makerspace & Robotics Lab', '2026-11-19T09:00:00+05:30', '2026-11-19T21:00:00+05:30', 200, 36, 'tech_robotics.jpg', true, true, '[]'::jsonb, ''),
  (14, 3, 2, '24-Hour Distributed Systems & AI Hackathon', 'Build resilient peer-to-peer applications, mesh networking tools, and local LLM agents', 'A full 24-hour sprint in the Makerspace with mentors from industry and open-source labs. Food, soldering irons, high-speed Wi-Fi, and server rigs provided.', 'Foundry Makerspace & Robotics Lab', '2026-11-19T09:00:00+05:30', '2026-11-20T09:00:00+05:30', 0, 45, 'tech_robotics.jpg', true, true, '[]'::jsonb, ''),
  (15, 3, 2, 'Campus Cyber-Defense CTF Challenge', 'Jeopardy-style security sprint spanning reverse engineering, web security, and cryptography', 'Compete individually or in pairs to crack vulnerability challenges, exploit buffer overflows, and analyze memory dumps on our isolated cyber range.', 'Foundry Makerspace & Robotics Lab', '2026-11-20T11:00:00+05:30', '2026-11-20T16:00:00+05:30', 0, 40, 'tech_robotics.jpg', false, true, '[]'::jsonb, ''),
  (27, 4, 3, 'Terracotta Wheel-Throwing Masterclass', 'Small-group intensive throwing technique, clay centering, and trimming ceramic forms', 'Two master ceramicists guide each participant on dedicated electric wheels. Includes glazing and kiln firing for one completed vessel.', 'Terracotta Craft & Print Studio', '2026-11-22T10:00:00+05:30', '2026-11-22T13:00:00+05:30', 350, 15, 'workshop_craft.jpg', true, true, '[]'::jsonb, ''),
  (7, 4, 3, 'Analog Cyanotype Sun-Printing Masterbench', 'Small-batch botanical sun-printing on handmade cotton rag paper', 'An ultra-intimate bench session mixing ferric ammonium citrate and potassium ferricyanide to expose architectural and botanical blueprints in direct afternoon sunlight.', 'Observatory Terrace & Lawn', '2026-11-22T14:30:00+05:30', '2026-11-22T16:30:00+05:30', 180, 1, 'workshop_craft.jpg', false, true, '[]'::jsonb, ''),
  (8, 4, 3, 'Kagaz & Lead: Movable Type & Risograph Zine Lab', 'Compose hand-set metal type and bind a 16-page two-color festival chapbook', 'A quiet, ink-stained afternoon for typographers, poets, and illustrators. Learn how to lock up lead type in a chase and print editioned zines on our studio risograph.', 'Terracotta Craft & Print Studio', '2026-11-23T11:00:00+05:30', '2026-11-23T14:00:00+05:30', 120, 20, 'workshop_craft.jpg', false, true, '[]'::jsonb, ''),
  (28, 4, 3, 'Woodblock Botanical Printmaking', 'Carve seasoned teak blocks and print repeating floral motifs on mulberry paper', 'Discover relief carving safely with Japanese gouges, mix water-based oil inks, and pull crisp botanical prints to take home.', 'Terracotta Craft & Print Studio', '2026-11-23T14:00:00+05:30', '2026-11-23T17:00:00+05:30', 200, 20, 'workshop_craft.jpg', false, true, '[]'::jsonb, ''),
  (29, 4, 3, 'Japanese Bookbinding & Zine Production', 'Hand-stitch lay-flat notebooks using four-hole stab binding and hand-marbled book covers', 'Fold, punch, and stitch elegant keepsake journals using cotton thread, bone folders, and recycled handmade paper stock.', 'Terracotta Craft & Print Studio', '2026-11-24T11:00:00+05:30', '2026-11-24T14:00:00+05:30', 180, 18, 'workshop_craft.jpg', false, true, '[]'::jsonb, ''),
  (43, 3, 1, 'Autumn Ceramic Showcase', 'Hands-on pottery exhibition', 'Exclusive live wheel throwing demonstration and showcase.', 'The Brick Lounge & Arcade Commons', '2026-11-25 10:00:00+05:30', '2026-11-25 12:30:00+05:30', 150, 40, 'hero_festival.jpg', false, true, '[]'::jsonb, ''),
  (26, 5, 4, 'Indie Game Developer Playtest & Showcase', 'Playtest unreleased student indie titles across PC, Game Boy emulators, and mobile builds', 'Meet student game directors, playtest experimental level designs, and vote for the community choice best gameplay mechanics award.', 'The Brick Lounge & Arcade Commons', '2026-11-27T10:00:00+05:30', '2026-11-27T13:00:00+05:30', 0, 35, 'gaming_arcade.jpg', false, true, '[]'::jsonb, ''),
  (23, 5, 4, 'Super Smash & Street Fighter Collegiate Cup', 'Double-elimination fighting game bracket on zero-latency tournament monitors', 'Campus fighting game masters clash in Super Smash Bros Ultimate and Street Fighter 6. Open registration bracket with live commentary.', 'The Brick Lounge & Arcade Commons', '2026-11-27T13:00:00+05:30', '2026-11-27T18:00:00+05:30', 0, 40, 'gaming_arcade.jpg', true, true, '[]'::jsonb, ''),
  (30, 7, 4, 'Inter-Collegiate 3v3 Floodlight Basketball', 'Fast-paced half-court hoops under tournament lights with DJ beats and student cheering', 'Sixteen college squads compete in round-robin pools leading to the knockout medal rounds. Fast break tempo and live court announcers.', 'Vivekananda Sports Complex & Arena', '2026-11-27T17:00:00+05:30', '2026-11-27T21:30:00+05:30', 0, 100, 'sports_arena.jpg', true, true, '[]'::jsonb, ''),
  (31, 7, 4, 'Fast-Paced Campus Table Tennis Knockout', 'Singles tournament on Olympic-grade tables with dynamic spin exchanges and rallies', 'Tiered draws for beginner and collegiate rated paddlers. High-speed rallies and medal presentations.', 'Vivekananda Sports Complex & Arena', '2026-11-28T10:00:00+05:30', '2026-11-28T14:00:00+05:30', 0, 48, 'sports_arena.jpg', false, true, '[]'::jsonb, ''),
  (33, 7, 4, 'Campus Sunset 5K Trail Run & Cross-Country', 'Scenic sunset 5K through tree-lined campus paths, lake bridges, and sports stadium track', 'A festive community run with chip-timing, water stations, cheering volunteer corners, and finisher souvenir medals.', 'Vivekananda Sports Complex & Arena', '2026-11-28T16:30:00+05:30', '2026-11-28T18:30:00+05:30', 0, 120, 'sports_arena.jpg', false, true, '[]'::jsonb, ''),
  (24, 5, 4, 'Midnight Blitz Chess & Strategy Arena', '3-minute blitz clocks, tactical puzzles, and giant board showdowns under warm lounge lights', 'Rapid calculations, tense endgames, and quiet camaraderie. Clocks and wooden pieces provided for all ranked rating brackets.', 'The Brick Lounge & Arcade Commons', '2026-11-28T20:00:00+05:30', '2026-11-28T23:30:00+05:30', 0, 32, 'gaming_arcade.jpg', false, true, '[]'::jsonb, ''),
  (32, 7, 4, 'Badminton Doubles Championship', 'Smash, drop, and dive in an electric campus indoor shuttlecock showdown', 'Inter-hostel and open collegiate pairs battle through qualifying rounds toward Sunday''s gold medal match.', 'Vivekananda Sports Complex & Arena', '2026-11-29T09:30:00+05:30', '2026-11-29T14:30:00+05:30', 120, 60, 'sports_arena.jpg', true, true, '[]'::jsonb, ''),
  (25, 5, 4, 'Valorant 5v5 Campus Showdown Finals', 'Main stage tactical FPS championship with stadium seating, shoutcasters, and team booths', 'The top 4 collegiate teams battle on the auditorium big screen in an intense best-of-three tactical shooter showcase.', 'Gulmohar Conservatory Hall', '2026-11-29T14:00:00+05:30', '2026-11-29T19:00:00+05:30', 100, 75, 'gaming_arcade.jpg', true, true, '[]'::jsonb, ''),
  (37, 8, 5, 'Genesis 10-Minute Venture Pitch Arena', 'Ten student startup finalists pitch early traction to venture capitalists and angel operators', 'Rapid-fire 10-minute pitches followed by live Q&A from active angel investors and venture mentors.', 'Tagore Incubation Hub & Auditorium', '2026-12-02T10:00:00+05:30', '2026-12-02T14:00:00+05:30', 0, 70, 'entrepreneur_pitch.jpg', true, true, '[]'::jsonb, ''),
  (39, 8, 5, 'Founders Speed-Dating & Tech Co-founder Mixer', 'Structured matchmaking for software coders, hardware engineers, and business designers', 'Fast-paced 5-minute rotational conversations connecting complementary skillsets looking to build new campus ventures.', 'Tagore Incubation Hub & Auditorium', '2026-12-02T16:00:00+05:30', '2026-12-02T18:30:00+05:30', 0, 45, 'entrepreneur_pitch.jpg', false, true, '[]'::jsonb, ''),
  (38, 8, 5, 'Hardware Prototype Demo Day & Angel Feedback', 'Hands-on exhibition of physical hardware prototypes, clean energy devices, and IoT sensors', 'Walk among live demo booths, inspect working hardware prototypes, and provide valuable user testing feedback.', 'Tagore Incubation Hub & Auditorium', '2026-12-03T14:00:00+05:30', '2026-12-03T18:00:00+05:30', 0, 60, 'entrepreneur_pitch.jpg', false, true, '[]'::jsonb, ''),
  (40, 8, 5, 'Social Impact Venture Case Competition', 'Teams develop and defend scalable business models addressing public health and education', 'Solve actual community challenges with rigorous unit economics and social impact metrics before an expert judging panel.', 'Tagore Incubation Hub & Auditorium', '2026-12-04T10:30:00+05:30', '2026-12-04T14:30:00+05:30', 150, 50, 'entrepreneur_pitch.jpg', true, true, '[]'::jsonb, ''),
  (35, 6, 6, 'Campus Heritage Architectural Walk', 'Guided walking tour exploring colonial terracotta arches, library vaults, and historic banyans', 'Led by architecture historians, uncover eighty years of campus structural evolution and forgotten architectural details.', 'Banyan Open-Air Amphitheatre', '2026-12-08T08:30:00+05:30', '2026-12-08T11:00:00+05:30', 0, 30, 'theatre_carnival.jpg', false, true, '[]'::jsonb, ''),
  (19, 2, 6, 'Bengali Folk Puppetry & Shadow Play', 'Traditional Beneputul string and shadow puppetry preserved by rural master puppeteers', 'A delightful family-friendly and heritage narrative passed down through five generations, featuring carved wooden puppets and harmonium ballads.', 'Gulmohar Conservatory Hall', '2026-12-08T15:00:00+05:30', '2026-12-08T17:00:00+05:30', 100, 50, 'theatre_carnival.jpg', false, true, '[]'::jsonb, ''),
  (36, 6, 6, 'Student Culinary Pop-up & Artisan Food Lane', 'Artisanal food lane featuring regional tribal recipes, fermented breads, and craft desserts', 'Over twenty student stalls prepare authentic family recipes, herbal teas, and regional sweets under festival canopies.', 'Banyan Open-Air Amphitheatre', '2026-12-09T12:00:00+05:30', '2026-12-09T18:00:00+05:30', 0, 100, 'theatre_carnival.jpg', true, true, '[]'::jsonb, ''),
  (17, 2, 6, 'Midnight Spoken Word & Monologue Circle', 'Intimate late-night poetic performances, vulnerability, and storytelling under candle lanterns', 'Writers, translators, and spoken-word artists share bilingual pieces in Bengali, Hindi, and English exploring city memories and youthful longings.', 'Gulmohar Conservatory Hall', '2026-12-09T21:00:00+05:30', '2026-12-09T23:00:00+05:30', 0, 60, 'theatre_carnival.jpg', false, true, '[]'::jsonb, ''),
  (18, 2, 6, 'Street Theatre on Social Change: Mukhomukhi', 'Powerful ensemble courtyard play examining environmental justice and campus voice', 'Performed in the round without microphones, this raw and resonant student production invites the audience into the courtyard center stage.', 'Banyan Open-Air Amphitheatre', '2026-12-10T16:30:00+05:30', '2026-12-10T18:30:00+05:30', 0, 90, 'theatre_carnival.jpg', true, true, '[]'::jsonb, ''),
  (22, 1, 6, 'Baul-Rock Fusion Live: Bauliana', 'Electrified ektara, dotara, and electric bass in an exhilarating sufi-folk rock celebration', 'A high-energy concert blending mystic Baul poetry with electric guitar riffs, khol rhythms, and soaring chorus chants.', 'Gulmohar Conservatory Hall', '2026-12-11T18:30:00+05:30', '2026-12-11T21:00:00+05:30', 250, 90, 'music_concert.jpg', true, true, '[]'::jsonb, '')
